Using PyMuPDF (fitz), I need to get precise text locations for redaction in all three papers. For each paper, extract the exact text blocks that need to be redacted.

Run this Python code:

```python
import fitz

# Paper 1 - check page 1 in detail for author block location
doc = fitz.open("/root/paper1.pdf")
page = doc[0]
print("=== PAPER 1, Page 1 - All text blocks with positions ===")
blocks = page.get_text("dict")["blocks"]
for b in blocks:
    if "lines" in b:
        for line in b["lines"]:
            text = "".join([s["text"] for s in line["spans"]])
            if text.strip():
                print(f"  bbox={line['bbox']}, text='{text[:120]}'")
print("\n=== PAPER 1, Page 2 - looking for GitHub URL ===")
page2 = doc[1]
blocks2 = page2.get_text("dict")["blocks"]
for b in blocks2:
    if "lines" in b:
        for line in b["lines"]:
            text = "".join([s["text"] for s in line["spans"]])
            if 'github' in text.lower() or 'VERA' in text:
                print(f"  bbox={line['bbox']}, text='{text[:200]}'")

# Check what the "Preprint" header looks like
for pn in range(min(5, len(doc))):
    p = doc[pn]
    blocks = p.get_text("dict")["blocks"]
    for b in blocks:
        if "lines" in b:
            for line in b["lines"]:
                text = "".join([s["text"] for s in line["spans"]])
                if 'preprint' in text.lower():
                    print(f"  Page {pn+1} header: bbox={line['bbox']}, text='{text}'")
doc.close()

# Paper 2 - check page 1 for author block and footer
doc = fitz.open("/root/paper2.pdf")
page = doc[0]
print("\n=== PAPER 2, Page 1 - All text blocks with positions ===")
blocks = page.get_text("dict")["blocks"]
for b in blocks:
    if "lines" in b:
        for line in b["lines"]:
            text = "".join([s["text"] for s in line["spans"]])
            if text.strip():
                print(f"  bbox={line['bbox']}, text='{text[:150]}'")

# Check acknowledgment section on page 4
page4 = doc[3]
print("\n=== PAPER 2, Page 4 - full text ===")
print(page4.get_text())

# Check all page footers
for pn in range(len(doc)):
    p = doc[pn]
    blocks = p.get_text("dict")["blocks"]
    for b in blocks:
        if "lines" in b:
            for line in b["lines"]:
                text = "".join([s["text"] for s in line["spans"]])
                if 'interspeech' in text.lower() or 'kos' in text.lower() or '2024' in text.lower():
                    print(f"  Page {pn+1} footer: bbox={line['bbox']}, text='{text[:200]}'")
doc.close()

# Paper 3 - check page 1 for author block
doc = fitz.open("/root/paper3.pdf")
page = doc[0]
print("\n=== PAPER 3, Page 1 - All text blocks with positions ===")
blocks = page.get_text("dict")["blocks"]
for b in blocks:
    if "lines" in b:
        for line in b["lines"]:
            text = "".join([s["text"] for s in line["spans"]])
            if text.strip():
                print(f"  bbox={line['bbox']}, text='{text[:150]}'")

# Check page 4 for GitHub URL
page4 = doc[3]
print("\n=== PAPER 3, Page 4 - looking for GitHub ===")
blocks4 = page4.get_text("dict")["blocks"]
for b in blocks4:
    if "lines" in b:
        for line in b["lines"]:
            text = "".join([s["text"] for s in line["spans"]])
            if 'github' in text.lower() or 'flops' in text.lower():
                print(f"  bbox={line['bbox']}, text='{text[:200]}'")

# Check funding info on page 1
for b in blocks:
    if "lines" in b:
        for line in b["lines"]:
            text = "".join([s["text"] for s in line["spans"]])
            if 'nsf' in text.lower() or 'aro' in text.lower() or 'support' in text.lower() or 'fund' in text.lower():
                print(f"  Funding on page 1: bbox={line['bbox']}, text='{text[:200]}'")
doc.close()
